var t=[{title:`Pornește de la zilele tale libere`,text:`Alege zilele în care chiar te poți antrena înainte să alegi o împărțire complicată. Cu două zile, un program pentru tot corpul luni și joi lasă câteva zile de refacere între ele. Cu trei, luni, miercuri și vineri este simplu. Cu patru, poți împărți două sesiuni superioare și două inferioare pe parcursul săptămânii. Acestea sunt exemple, iar și alte aranjamente funcționează.`},{title:`Refacerea între sesiunile înrudite`,text:`Mulți începători se descurcă bine cu aproximativ una sau două zile între antrenamentele grele pentru aceiași mușchi, mai ales cât durerea musculară este încă nouă pentru ei. Cele 48 de ore citate adesea sunt o regulă practică. Istoricul tău de antrenament, efortul, alegerea exercițiilor și somnul schimbă toate cât de multă refacere ai nevoie.`},{title:`Unde pui munca grea`,text:`Ridicările grele și cele care cer multă îndemânare merg mai bine când ești destul de odihnit. Balansările din șold, genuflexiunile și intervalele de sprint foarte solicitante în zile consecutive pot acumula oboseală de care nu ai nevoie. Mersul ușor sau munca de mobilitate pot intra între zilele de forță și nu contează ca un alt antrenament greu.`},{title:`O săptămână flexibilă`,text:`Dacă ratezi un antrenament, mută-l într-o zi liberă sau continuă cu următoarea sesiune. Nu înghesui toată munca ratată într-o singură zi și nu pune sesiuni grele pentru aceeași mișcare una peste alta doar ca să atingi un număr săptămânal. Urmărește-ți performanța și oboseala pe parcursul mai multor săptămâni. Fiecare săptămână calendaristică nu are nevoie de același volum.`},{title:`Folosirea TrainUp`,text:`În Profil stabilești câte zile pe săptămână te antrenezi, cât durează o sesiune și ce zile preferi, iar le poți schimba oricând. Din Panou poți activa mementouri de antrenament pentru zilele și orele alese. Istoricul arată antrenamentele din această săptămână, efortul tău mediu și un grafic pe 4 săptămâni, care te ajută să urmărești oboseala pe parcursul săptămânilor.`}];var a=[{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NHS: ghid despre forță și flexibilitate`,url:`https://www.nhs.uk/live-well/exercise/how-to-improve-strength-flexibility/`},{label:`NSCA: bazele siguranței și ale antrenamentului de forță`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var r={sections:t,sources:a};export{r as default,t as sections,a as sources};